// KPI definitions of CONTRACT.md Section 9.5, computed from the index. A KPI that cannot be computed from real data is null with the reason.
import { sql } from 'drizzle-orm';
import type { Kpi, KpiCriterion } from '../contract/contract.js';
import type { Ctx } from '../context.js';
import { isoSeconds } from './dates.js';

const rows = async <T>(ctx: Ctx, q: ReturnType<typeof sql>) => (await ctx.db.execute(q)) as unknown as T[];
const pct = (n: number, d: number) => Math.round((n / d) * 1000) / 10;

export async function computeKpis(ctx: Ctx): Promise<{ items: Kpi[]; asOf: string }> {
  const asOf = isoSeconds(ctx.now());
  const mk = (key: string, label: string, value: number | null, unit: string, computedFrom: string, target?: string, numerator?: number, denominator?: number): Kpi =>
    ({ key, label, value, unit, ...(target ? { target } : {}), ...(numerator !== undefined ? { numerator } : {}), ...(denominator !== undefined ? { denominator } : {}), computedFrom, asOf });

  // 1. price premium: avg settled price per quintal (grade A) / AGMARKNET modal, same commodity, same week, Medinipur (West), minus 1
  const prem = await rows<{ commodity: string; price: number; qtl: number; modal: number | null }>(ctx, sql`
    select l.commodity, p.price_per_qtl as price, sum(l.net_kg)/100.0 as qtl,
      (select avg(s.modal_price) from price_series s where lower(s.commodity) = lower(l.commodity)
         and lower(replace(s.market,' ','')) like 'medinipur(west)%' and abs(s.date - (o.order->>'settledAt')::date) <= 3) as modal
    from orders_view o join trade_prices p on p.order_id = o.order_id join lots_view l on l.order_id = o.order_id
    where o.status = 'SETTLED' and l.grade = 'A' and l.status in ('SETTLED','CLOSED') group by l.commodity, p.price_per_qtl, o.order`);
  const usable = prem.filter((r) => r.modal != null && Number(r.modal) > 0);
  const premium = usable.length ? usable.reduce((a, r) => a + (r.price / Number(r.modal) - 1) * r.qtl, 0) / usable.reduce((a, r) => a + r.qtl, 0) : null;

  // 2. post-harvest loss
  const [loss] = await rows<{ acc: number | null; est: number | null }>(ctx, sql`select sum(net_kg) as acc, sum(est_weight_kg) as est from lots_view where lot->>'qualityOutcome' = 'ACCEPTED'`);
  // 3. pledge finance reach
  const [reach] = await rows<{ withLien: number; storable: number; value: number | null }>(ctx, sql`
    select (select count(distinct l.farmer_token) from lots_view l join liens_view li on li.sscc = l.sscc)::int as "withLien",
           (select count(distinct farmer_token) from lots_view where status in ('IN_STORAGE','PLEDGED','LISTED','SOLD','IN_TRANSIT','DELIVERED','SETTLED','CLOSED') and lot->>'facility' <> '')::int as storable,
           (select sum(amount) from loan_terms) as value`);
  // 4. payment cycle: median days PriceAgreed -> PatronageDistributed per order
  const cyc = await rows<{ days: number }>(ctx, sql`
    select extract(epoch from (pd.at - pa.at))/86400.0 as days from ledger_events pa join ledger_events pd on pd.order_id = pa.order_id
    where pa.event = 'PriceAgreed' and pd.event = 'PatronageDistributed'`);
  const days = cyc.map((c) => Number(c.days)).sort((a, b) => a - b);
  const median = days.length ? (days.length % 2 ? days[(days.length - 1) / 2]! : (days[days.length / 2 - 1]! + days[days.length / 2]!) / 2) : null;
  // 5. statement views
  const [sv] = await rows<{ viewed: number; settled: number }>(ctx, sql`
    select (select count(distinct subject) from telemetry where kind = 'MemberStatementViewed')::int as viewed,
           (select count(distinct farmer_token) from lots_view where status in ('SETTLED','CLOSED'))::int as settled`);
  // 6. time to trace
  const lat = await rows<{ ms: number }>(ctx, sql`select latency_ms as ms from telemetry where kind = 'ProvenanceQueried' and latency_ms is not null order by latency_ms`);
  const p50 = lat.length ? lat[Math.floor((lat.length - 1) / 2)]!.ms : null;
  // 7. audit divergence
  const [au] = await rows<{ audited: number; divergent: number }>(ctx, sql`select count(*) filter (where status <> 'PENDING')::int as audited, count(*) filter (where status = 'DIVERGENT')::int as divergent from audits`);
  // 8. women's participation and members with a lot
  const [wp] = await rows<{ women: number; withLot: number; members: number }>(ctx, sql`
    select count(distinct f.id) filter (where f.gender = 'F')::int as women, count(distinct f.id)::int as "withLot", (select count(*) from farmers where not erased)::int as members
    from farmers f join lots_view l on l.farmer_token = f.token where not f.erased`);
  const [loans] = await rows<{ n: number }>(ctx, sql`select count(*)::int as n from liens_view where loan->>'status' in ('DISBURSED','REPAID','RELEASED')`);

  const items: Kpi[] = [
    mk('price_premium', 'Realised price premium', premium === null ? null : Math.round(premium * 1000) / 10, '%', premium === null ? 'No settled grade A order has an AGMARKNET modal price for the same week at Medinipur (West) in the index yet' : `Quantity-weighted over ${usable.length} settled grade A order line(s) against the AGMARKNET modal price within 3 days of settlement`, '+8%'),
    mk('post_harvest_loss', 'Post-harvest loss', loss?.est ? Math.round((1 - Number(loss.acc) / Number(loss.est)) * 1000) / 10 : null, '%', loss?.est ? 'Lots accepted by the buyer: graded net kg (weighbridge) against kg estimated at commissioning, weight-weighted' : 'No lot has been accepted by a buyer yet', '< 8%', loss?.est ? Number(loss.acc) : undefined, loss?.est ? Number(loss.est) : undefined),
    mk('pledge_reach', 'Pledge finance reach', reach && reach.storable ? pct(reach.withLien, reach.storable) : null, '%', reach?.storable ? `Members with a lien over members with stored lots. Value facilitated INR ${Number(reach.value ?? 0).toLocaleString('en-IN')}` : 'No lot is in storage yet', '35%', reach?.withLien, reach?.storable),
    mk('payment_cycle', 'Payment cycle', median === null ? null : Math.round(median * 10) / 10, 'days', median === null ? 'No order has reached patronage distribution yet' : `Median over ${days.length} order(s), PriceAgreed to PatronageDistributed event time`, '< 7 days'),
    mk('statement_views', 'Statement views', sv && sv.settled ? pct(sv.viewed, sv.settled) : null, '%', sv?.settled ? 'Members who opened a statement (telemetry MemberStatementViewed) over members with a settled lot' : 'No member has a settled lot yet', '70%', sv?.viewed, sv?.settled),
    mk('time_to_trace', 'Time to trace (p50)', p50, 'ms', p50 === null ? 'No provenance query has been measured yet' : `Median server time of ${lat.length} GET /public/provenance call(s)`, '< 5 s'),
    mk('audit_divergence', 'Audit divergence', au && au.audited ? pct(au.divergent, au.audited) : null, '%', au?.audited ? 'Divergent re-inspections over lots audited' : 'No re-inspection has been recorded yet', '< 5%', au?.divergent, au?.audited),
    mk('women_participation', "Women's participation", wp && wp.withLot ? pct(wp.women, wp.withLot) : null, '%', wp?.withLot ? 'Women with at least one lot over members with at least one lot' : 'No member has a lot yet', '>= 40%', wp?.women, wp?.withLot),
  ];
  const criteria: KpiCriterion[] = [
    { key: 'members_with_lot', label: 'At least 60% of members have at least one recorded lot', met: wp?.members ? wp.withLot / wp.members >= 0.6 : null, evidence: wp?.members ? `${wp.withLot} of ${wp.members} members` : 'No members registered' },
    { key: 'audit_divergence', label: 'First-mile audit divergence below 5%', met: au?.audited ? au.divergent / au.audited < 0.05 : null, evidence: au?.audited ? `${au.divergent} divergent of ${au.audited} audited` : 'No audits recorded yet' },
    { key: 'lender_disbursed', label: 'At least one lender disbursed against a platform-evidenced e-NWR', met: (loans?.n ?? 0) > 0, evidence: `${loans?.n ?? 0} loan(s) disbursed against an e-NWR on the ledger` },
    { key: 'buyer_premium', label: 'At least one buyer paid a measurable premium on a verified-origin consignment', met: premium === null ? null : premium > 0, evidence: premium === null ? 'The premium cannot be measured until AGMARKNET prices cover a settled grade A order' : `Premium ${Math.round(premium * 1000) / 10}% over the AGMARKNET modal price` },
  ];
  const met = criteria.filter((c) => c.met === true).length;
  items.push({ ...mk('month12_gate', 'Month-12 gate', met, 'criteria met', 'Four criteria given by the team (CONTRACT.md Section 9.5); a criterion is undetermined (met: null) until its data exists', 'all 4', met, 4), criteria });
  return { items, asOf };
}
